import { useState, useEffect } from 'react';
import axios from 'axios';

export default function EmployeesPage() {
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const initial = { name: '', designation: '', department: '', ctc: '', joining_date: '', last_working_day: '', status: 'active', email: '', phone: '' };
  const [form, setForm] = useState(initial);

  const load = () => {
    setLoading(true);
    axios.get('/api/employees/').then(r => setEmployees(r.data)).finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, []);

  const openCreate = () => { setForm(initial); setEditing(null); setShowModal(true); setError(''); };
  const openEdit = (emp) => { setForm({ ...emp }); setEditing(emp._id); setShowModal(true); setError(''); };

  const handleSubmit = async (e) => {
    e.preventDefault(); setError('');
    try {
      if (editing) {
        await axios.put(`/api/employees/${editing}`, form);
        setSuccess('Employee updated');
      } else {
        await axios.post('/api/employees/', form);
        setSuccess('Employee created');
      }
      setShowModal(false); load();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError(err.response?.data?.error || 'Error saving');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this employee?')) return;
    await axios.delete(`/api/employees/${id}`);
    load();
  };

  const filtered = employees.filter(e =>
    e.name?.toLowerCase().includes(search.toLowerCase()) ||
    e.employee_id?.toLowerCase().includes(search.toLowerCase()) ||
    e.designation?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Employees</h1>
          <p className="page-subtitle">{employees.length} total · {employees.filter(e => e.status === 'active').length} active</p>
        </div>
        <button className="btn btn-primary" onClick={openCreate}>+ Add Employee</button>
      </div>

      {success && <div className="alert alert-success">{success}</div>}

      <div className="card">
        <div style={{ marginBottom: 16 }}>
          <input placeholder="Search by name, ID, or designation..." value={search} onChange={e => setSearch(e.target.value)} style={{ maxWidth: 360 }} />
        </div>

        {loading ? <div className="page-loading"><div className="spinner" /></div> : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Employee ID</th>
                  <th>Name</th>
                  <th>Designation</th>
                  <th>Department</th>
                  <th>CTC</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filtered.length === 0 ? (
                  <tr><td colSpan={7}><div className="empty-state"><div className="empty-icon">◉</div><p>No employees found</p></div></td></tr>
                ) : filtered.map(emp => (
                  <tr key={emp._id}>
                    <td><span className="mono">{emp.employee_id}</span></td>
                    <td>
                      <div style={{ fontWeight: 500 }}>{emp.name}</div>
                      {emp.email && <div className="text-sm text-muted">{emp.email}</div>}
                    </td>
                    <td>{emp.designation}</td>
                    <td>{emp.department || '—'}</td>
                    <td><span className="mono">₹{emp.ctc || '—'}</span></td>
                    <td>
                      <span className={`badge ${emp.status === 'active' ? 'badge-green' : 'badge-amber'}`}>
                        {emp.status}
                      </span>
                    </td>
                    <td>
                      <div style={{ display: 'flex', gap: 6 }}>
                        <button className="btn btn-sm btn-secondary" onClick={() => openEdit(emp)}>Edit</button>
                        <button className="btn btn-sm btn-danger" onClick={() => handleDelete(emp._id)}>Del</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {showModal && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setShowModal(false)}>
          <div className="modal">
            <h2 className="modal-title">{editing ? 'Edit Employee' : 'Add Employee'}</h2>
            {error && <div className="alert alert-error">{error}</div>}
            <form onSubmit={handleSubmit}>
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Full Name *</label>
                  <input required value={form.name} onChange={e => setForm({...form, name: e.target.value})} placeholder="John Doe" />
                </div>
                <div className="form-group">
                  <label className="form-label">Email</label>
                  <input type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="john@company.com" />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Designation *</label>
                  <input required value={form.designation} onChange={e => setForm({...form, designation: e.target.value})} placeholder="Software Engineer" />
                </div>
                <div className="form-group">
                  <label className="form-label">Department</label>
                  <input value={form.department} onChange={e => setForm({...form, department: e.target.value})} placeholder="Engineering" />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">CTC</label>
                  <input value={form.ctc} onChange={e => setForm({...form, ctc: e.target.value})} placeholder="8,00,000" />
                </div>
                <div className="form-group">
                  <label className="form-label">Status</label>
                  <select value={form.status} onChange={e => setForm({...form, status: e.target.value})}>
                    <option value="active">Active</option>
                    <option value="exited">Exited</option>
                  </select>
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Joining Date</label>
                  <input type="date" value={form.joining_date} onChange={e => setForm({...form, joining_date: e.target.value})} />
                </div>
                <div className="form-group">
                  <label className="form-label">Last Working Day</label>
                  <input type="date" value={form.last_working_day} onChange={e => setForm({...form, last_working_day: e.target.value})} />
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary">{editing ? 'Update' : 'Create'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
